window.NPC_CHUNK_245 = [{"name":"Castothrane","cr":12,"xp":19200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":11}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["human"],"templates_applied":"skeleton warrior","init":5,"senses":["darkvision 60 ft."],"auras":["fear aura (DC 15)"],"ac":28,"ac_touch":11,"ac_flat_footed":27,"ac_mods":"+10 armor, +1 Dex, +4 natural, +3 shield","hp":142,"hd":"11d10+77","hd_value":11,"fort":15,"ref":7,"will":7,"save_mods":"Will: +3 vs. fear","dr":"10/bludgeoning and magic","immunities":["channel energy","undead traits"],"sr":27,"speed":[{"type":"land","speed":30}],"melee":"+1 battleaxe +20 (1d8+9/19-20/x3)","ranged":"mwk composite longbow +14 (1d8+5/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"axes +2, bows +1"}],"strength":18,"dexterity":12,"intelligence":8,"wisdom":12,"charisma":20,"baseatk":11,"cmb":15,"cmb_special":"+17 bull rush","cmd":26,"cmd_special":"28 vs. bull rush","feats":[{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Greater Weapon Focus (battleaxe)"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (battleaxe)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (battleaxe)"},{"feat":"Weapon Specialization (battleaxe)"}],"skills":[{"skill":"Intimidate","value":27},{"skill":"Perception","value":7},{"skill":"Ride","value":12},{"skill":"Sense Motive","value":7}],"languages":["Common"],"sq":["armor training 3","find target"],"special_abilities":[{"type":"Fear Aura","kind":"Su","details":"Castothrane is shrouded in an aura of fear. Creatures with fewer than 5 Hit Dice and in a 30-foot radius must succeed at a DC 15 Will save or be affected as per fear (CL 11th)."},{"type":"Find Target","kind":"Sp","details":"Castothrane can track and find the holder of his circlet unerringly, as though guided by discern location (CL 11th). Using this ability, he can also find the last person to hold his circlet. His caster level is equal to the total of his Hit Dice."}],"gear":"+1 full plate, +1 heavy steel shield, +1 battleaxe, mwk composite longbow (+4 Str) with 20 arrows, cloak of resistance +1, ring of immolation","during_combat":"Castothrane uses Power Attack when he fights. As he does, he attempts to maneuver the battle out onto one of the nearby parapets, so he can attempt to bull rush enemies off the edge (anyone who topples from either parapet takes 6d6 points of damage from the fall to the rocky shoreline below). Although Castothrane would like nothing better than to pursue fleeing enemies, his orders are to remain on this floor of the gatehouse no matter what.","morale":"Castothrane fights until destroyed, or until he receives his circlet.","source":"Curse Of The Crimson Throne Chapter 5, Tome of Horrors Complete 734"},{"name":"Nihil The Ashbringer","cr":13,"xp":25600,"race":"ashmede devil","gender":"Female","age_category":"Adult","alignment":"LE","size":"Large","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":7,"senses":["aura sight","darkvision 60 ft.","detect magic","see in darkness"],"auras":["fear (30 ft., DC 19)"],"ac":30,"ac_touch":14,"ac_flat_footed":27,"ac_mods":"+2 deflection, +3 Dex, +16 natural, -1 size","hp":175,"hd":"13d10+104","hd_value":13,"hp_mods":"fast healing 3","fort":16,"ref":7,"will":11,"dr":"10/good","immunities":["fire","poison"],"resists":["acid 10","cold 10"],"sr":24,"speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":40}],"melee":"+1 unholy scythe +21 (2d6+11/19-20/x4), 2 wings +14 (1d6+3)","space":"10 ft.","reach":"10 ft.","spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"aura sight"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"charm person"},{"spell":"dispel magic"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"}]},{"frequency":"1/day","spells":[{"spell":"chain lightning"},{"spell":"discern location"},{"spell":"forcecage"},{"spell":"horrid wilting"},{"spell":"summon","details":"1 barbed devil 50%, level 4"}]},{"frequency":"3/day","spells":[{"spell":"blasphemy"},{"spell":"greater invisibility"},{"spell":"polymorph"},{"spell":"prying eyes"}]}],"strength":24,"dexterity":16,"constitution":26,"intelligence":17,"wisdom":17,"charisma":17,"baseatk":13,"cmb":21,"cmb_special":"+25 sunder","cmd":36,"cmd_special":"38 vs. sunder","feats":[{"feat":"Flyby Attack"},{"feat":"Greater Sunder"},{"feat":"Improved Critical (scythe)"},{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Power Attack"},{"feat":"Weapon Focus (scythe)"}],"skills":[{"skill":"Bluff","value":19},{"skill":"Diplomacy","value":19},{"skill":"Fly","value":17},{"skill":"Intimidate","value":19},{"skill":"Knowledge (nobility)","value":12},{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":19},{"skill":"Stealth","value":15},{"skill":"Survival","value":19}],"languages":["Celestial","Draconic","Infernal","telepathy 100 ft."],"special_abilities":[{"type":"Fear Aura","kind":"Su","details":"A creature that succumbs to Nihil's fear aura cowers in fear for 1 round."}],"gear":"+1 unholy scythe, ring of protection +2","before_combat":"As soon as she receives reports that the castle is being invaded by the PCs, Nihil uses prying eyes to explore Scarwall's heights in search of the intruders. If she finds them, she watches their tactics to familiarize herself with their capabilities. As soon as it looks like the PCs are about to reach this chamber, she casts greater invisibility and attempts to summon a barbed devil to augment her defenses.","during_combat":"When Nihil attacks, any minions she has nearby attempt to isolate individuals and wear them down before switching to other targets, letting Nihil make as many final kills as possible. As soon as the PCs are all within this chamber, she casts blasphemy, followed in the next 2 rounds by horrid wilting and chain lightning. If one PC in particular seems to be far more dangerous than others (such as a heavily armored fighter with weapons that can penetrate her damage reduction), she uses forcecage to separate that character from the battle to be dealt with later.","morale":"Nihil is unable to flee as long as she remains a spirit anchor, and thus fights to the death.","source":"Curse Of The Crimson Throne Chapter 5, The Book of Fiends 146"},{"name":"Gorstav","cr":13,"xp":25600,"race":"half-Orc","age_category":"Adult","classes":[{"class":"fighter","level":13}],"alignment":"NE","size":"Medium","type":"undead","sub_types":["human","orc"],"templates_applied":"juju zombie","init":6,"senses":["darkvision 60 ft."],"ac":27,"ac_touch":14,"ac_flat_footed":24,"ac_mods":"+10 armor, +1 deflection, +2 Dex, +1 dodge, +3 natural","hp":154,"hd":"13d10+78","hd_value":13,"fort":14,"ref":6,"will":4,"save_mods":"Will: +3 vs. fear","defensive_abilities":["channel resistance +4","Orc ferocity"],"dr":"10/magic and slashing","immunities":["cold","electricity","magic missile","undead traits"],"resists":["fire 10"],"speed":[{"type":"land","speed":30}],"melee":"+2 thundering warhammer +26 (1d8+18/19-20/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"hammers +3, bows +2, close +1"}],"strength":22,"dexterity":14,"intelligence":8,"wisdom":10,"charisma":18,"baseatk":13,"cmb":19,"cmb_special":"+21 bull rush","cmd":33,"cmd_special":"35 vs. bull rush","feats":[{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Greater Weapon Focus (warhammer)"},{"feat":"Greater Weapon Specialization (warhammer)"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (warhammer)"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Spring Attack"},{"feat":"Staggering Critical"},{"feat":"Toughness"},{"feat":"Weapon Focus (warhammer)"},{"feat":"Weapon Specialization (warhammer)"}],"skills":[{"skill":"Climb","value":12},{"skill":"Handle Animal","value":13},{"skill":"Intimidate","value":6},{"skill":"Ride","value":10}],"languages":["Common","Orc"],"sq":["armor training 3","Orc blood"],"gear":"+1 full plate, +2 thundering warhammer, belt of giant strength +2, ring of protection +1","during_combat":"Although Gorstav retains his military training, he fights without emotion of any kind, almost as if he were little more than a construct programmed to mimic an accomplished fighter's skills. He wields his warhammer two-handed in order to maximize his Strength bonus to damage.","morale":"Gorstav fights until destroyed.","source":"Curse Of The Crimson Throne Chapter 5, Pathfinder RPG Bestiary 2 291"},{"name":"Mingorc","cr":13,"xp":25600,"race":"ash giant","age_category":"Adult","alignment":"LE","size":"Large","type":"undead","sub_types":["giant"],"templates_applied":"advanced, juju zombie","init":9,"senses":["darkvision 60 ft.","low-light vision"],"ac":29,"ac_touch":14,"ac_flat_footed":24,"ac_mods":"+5 Dex, +15 natural, -1 size","hp":105,"hd":"14d8+42","hd_value":14,"fort":6,"ref":9,"will":12,"defensive_abilities":["channel resistance +4","rock catching"],"dr":"10/magic and slashing","immunities":["cold","electricity","magic missile","undead traits"],"resists":["fire 10"],"speed":[{"type":"land","speed":40}],"melee":"2 slams +24 (2d6+15 plus disease)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"disease","details":"DC 17"},{"type":"rock throwing","details":"120 feet"}],"strength":41,"dexterity":20,"intelligence":13,"wisdom":16,"charisma":14,"baseatk":10,"cmb":26,"cmd":41,"feats":[{"feat":"Catch Off-Guard"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Initiative"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Self-Sufficient"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":37},{"skill":"Heal","value":21},{"skill":"Intimidate","value":19},{"skill":"Perception","value":20},{"skill":"Survival","value":21}],"languages":["Common","Giant"],"sq":["oversized weapon","wild empathy +16"],"during_combat":"Mingorc stands in the center of the room, where he has fallen into a torpor. The undead giant remains motionless for 2 rounds after any PCs come into view, after which point he rouses and attacks. If the PCs attack before this, they gain an automatic surprise round before Mingorc reacts normally.","morale":"Mingorc pursues foes throughout the donjon, but will not exit the structure. Otherwise, he fights until destroyed.","source":"Curse Of The Crimson Throne Chapter 5, Pathfinder RPG Bestiary 3 290, 126, Pathfinder RPG Bestiary 2 291"},{"name":"Prelate Aruth","cr":13,"xp":25600,"race":"human","age_category":"Adult","classes":[{"class":"cleric of zon-kuthon","level":12}],"alignment":"LE","size":"Medium","type":"undead","sub_types":["human","humanoid"],"templates_applied":"mummy lord","init":5,"senses":["darkvision 60 ft."],"auras":["great despair (30 ft., DC 23)"],"ac":32,"ac_touch":16,"ac_flat_footed":30,"ac_mods":"+10 armor, +4 deflection, +1 Dex, +1 dodge, +6 natural","hp":165,"hd":"12d8+108","hd_value":12,"fort":17,"ref":7,"will":15,"defensive_abilities":["channel resistance +4","death's embrace","freedom of movement","rejuvenation"],"dr":"10/-","immunities":["cold","electricity","undead traits"],"sr":24,"speed":[{"type":"land","speed":20}],"speed_mod":"air walk","melee":"+2 keen spiked chain +15 (2d4+8/19-20 plus insidious mummy rot) or slam +8 (1d6+2 plus insidious mummy rot)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"10/day, DC 23, 6d6"},{"type":"channel rot"},{"type":"insidious mummy rot"},{"type":"sandstorm wrath","details":"8d8 fire and slashing, DC 23"},{"type":"undead mastery","details":"DC 23"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"8/day","spells":[{"spell":"bleeding touch","details":"6 rounds"},{"spell":"touch of darkness","details":"6 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":12,"spellsprepared_concentration":17,"spellsprepared":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"blade barrier"},{"spell":"create undead","type":"domain"},{"spell":"harm"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"plane shift"},{"spell":"slay living","type":"domain","count":3},{"spell":"spell resistance"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"air walk"},{"spell":"freedom of movement"},{"spell":"poison"},{"spell":"shadow conjuration","type":"domain"},{"spell":"unholy blight"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"animate dead"},{"spell":"bestow curse"},{"spell":"deeper darkness","type":"domain"},{"spell":"dispel magic","count":2},{"spell":"invisibility purge"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"blindness/deafness","type":"domain"},{"spell":"hold person","count":2},{"spell":"resist energy"},{"spell":"sound burst"},{"spell":"spiritual weapon"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"command","count":3},{"spell":"obscuring mist","type":"domain"},{"spell":"sanctuary","count":2},{"spell":"shield of faith"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"light"},{"spell":"mending"},{"spell":"read magic"}]}],"spelldomains":"Darkness, Death","strength":18,"dexterity":13,"intelligence":12,"wisdom":20,"charisma":24,"baseatk":9,"cmb":13,"cmd":25,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Casting"},{"feat":"Command Undead"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wondrous Item"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Selective Channeling"},{"feat":"Toughness"}],"skills":[{"skill":"Intimidate","value":30},{"skill":"Knowledge (religion)","value":16},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":13},{"skill":"Spellcraft","value":16},{"skill":"Stealth","value":5}],"languages":["Common","Shadowtongue"],"sq":["eyes of darkness (6 rounds/day)"],"gear":"+4 chainmail, +2 keen spiked chain, cloak of resistance +2, headband of mental prowess +2 (Wis, Cha), pouch of two dozen onyx gems (worth 2,800 gp total), iron unholy symbol of Zon-Kuthon","before_combat":"Prelate Aruth casts air walk, freedom of movement, shield of faith, and spell resistance.","during_combat":"Prelate Aruth prefers to cast spells in melee combat, favoring slay living and other touch spells, but does cast spiritual weapon on the first round of a fight,  targeting an enemy healer. If he kills a PC and feels he has the upper hand in combat, the prelate isn't above gloating and taking actions in combat that are more for cruelty's sake (such as animating a fallen PC into a zombie) than tactically sound, but when facing dangerous foes, he makes a fighting retreat toward area F11 so he can gain the support of the bishop therein.","morale":"The prelate fights until destroyed but doesn't pursue foes out of the donjon.","source":"Curse Of The Crimson Throne Chapter 5, Pathfinder RPG Bestiary 5 176"},{"name":"Yzahnum","cr":15,"xp":51200,"race":"efreeti","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":4},{"class":"rogue","level":7}],"alignment":"LE","size":"Large","type":"outsider","sub_types":["extraplanar","fire"],"init":10,"senses":["darkvision 60 ft.","detect magic"],"ac":30,"ac_touch":18,"ac_flat_footed":23,"ac_mods":"+4 armor, +2 deflection, +6 Dex, +1 dodge, +8 natural, -1 size","hp":238,"hd":"7d8+14d10+130","hd_value":21,"fort":15,"ref":19,"will":13,"save_mods":"Will: +1 vs. fear","defensive_abilities":["evasion","trap sense +2","uncanny dodge"],"immunities":["fire"],"resists":["cold 10"],"weaknesses":["vulnerable to cold"],"speed":[{"type":"fly","speed":40,"maneuverability":"perfect"},{"type":"land","speed":20}],"melee":"(as Trifaccia) Medium +1 flaming scimitar +29 (1d6+15/15-20 plus 1d6 fire) (as Yzahnum) Medium +1 flaming scimitar +26 (1d6+15/15-20 plus 1d6 fire), slam +21 (1d8+4 plus 1d6 fire) or 2 slams +26 (1d8+8 plus 1d6 fire)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"heat"},{"type":"sneak attack","details":"+4d6"}],"spell_like_abilities_caster_level":11,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"plane shift","details":"or Material Plane only, Astral Plane, willing targets to the Elemental Planes"},{"spell":"produce flame"},{"spell":"pyrotechnics"},{"spell":"scorching ray"}]},{"frequency":"1/day","spells":[{"spell":"gaseous form"},{"spell":"permanent image"}]},{"frequency":"2/day","spells":[{"spell":"change size"}]},{"frequency":"3/day","spells":[{"spell":"quickened invisibility"},{"spell":"quickened scorching ray"},{"spell":"wall of fire"},{"spell":"wish","details":"to non-genies only"}]}],"strength":26,"dexterity":23,"constitution":22,"intelligence":12,"wisdom":12,"charisma":18,"baseatk":19,"cmb":28,"cmd":47,"feats":[{"feat":"Blinding Critical"},{"feat":"Combat Casting"},{"feat":"Combat Reflexes"},{"feat":"Critical Focus"},{"feat":"Deceitful"},{"feat":"Dodge"},{"feat":"Improved Critical (scimitar)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (invisibility)"},{"feat":"Quicken Spell-Like Ability (scorching ray)"},{"feat":"Spring Attack"},{"feat":"Weapon Focus (scimitar)"},{"feat":"Weapon Specialization (scimitar)"}],"skills":[{"skill":"Bluff","value":32},{"skill":"Craft (weapon)","value":23},{"skill":"Diplomacy","value":22},{"skill":"Disguise","value":27},{"skill":"Fly","value":12},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":19},{"skill":"Spellcraft","value":25},{"skill":"Stealth","value":20}],"languages":["Common","Aquan","Auran","Ignan","Terran","telepathy 100 ft."],"sq":["armor training 1","change shape (humanoid or giant; alter self or giant form I)","rogue talents (combat trick, offensive defense, resiliency)","trapfinding +3"],"gear":"Medium +1 flaming scimitar, bracers of armor +4, minor ring of cold resistance, ring of protection +2","during_combat":"As Trifaccia, Yzahnum avoids the use of his spell-like abilities. When he fights in Human form, his size is Medium, making his AC is 1 higher, and he uses his \"Melee (as Trifaccia)\" attack. If he is reduced to fewer than 150 hit points, he reverts to his true form so he can use flight, cast scorching ray and wall of fire, and use change size to shrink foes. He reverts to melee only as necessary.","morale":"Yzahnum knows when he's outmatched. If reduced to 50 hit points or fewer, he attempts to escape via invisibility and flies back to Castle Korvosa-the terms of his current bargain with Ileosa prevents him from using plane shift to do so. If he escapes, the PCs might encounter him again once they begin to explore the castle.","source":"Curse Of The Crimson Throne Chapter 6, Pathfinder RPG Bestiary 140"},{"name":"Zarmangarof","cr":15,"xp":51200,"race":"very old black dragon","gender":"Male","age_category":"very old","alignment":"CE","size":"Huge","type":"dragon","sub_types":["water"],"init":4,"senses":["dragon senses"],"auras":["frightful presence (270 ft., DC 23)"],"ac":43,"ac_touch":8,"ac_flat_footed":43,"ac_mods":"+4 armor, +27 natural, +4 shield, -2 size","hp":250,"hd":"20d12+120","hd_value":20,"fort":18,"ref":12,"will":16,"dr":"15/magic","immunities":["acid","paralysis","sleep"],"sr":26,"speed":[{"type":"fly","speed":200,"maneuverability":"poor"},{"type":"land","speed":60},{"type":"swim","speed":60}],"melee":"bite +29 (2d8+15 plus 2d6 acid), 2 claws +28 (2d6+10), tail slap +26 (2d6+15), 2 wings +26 (1d8+5)","space":"15 ft.","reach":"10 ft. (15 ft. with bite)","special_attacks":[{"type":"acidic bite"},{"type":"breath weapon","details":"100-ft. line, DC 26, 18d6 acid"},{"type":"crush","details":"Small creatures, DC 26, 2d8+15"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":23,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"speak with animals","details":"reptiles only"}]},{"frequency":"at-will","spells":[{"spell":"darkness","details":"90-ft. radius"},{"spell":"plant growth"}]},{"frequency":"1/day","spells":[{"spell":"corrupt water"}]}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":9,"spellsknown_concentration":12,"spellsknown":[{"spell_level":4,"spell_slots":4,"spells":[{"spell":"hallucinatory terrain"},{"spell":"phantasmal killer"}]},{"spell_level":3,"spell_slots":7,"spells":[{"spell":"major image"},{"spell":"slow"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"glitterdust"},{"spell":"mirror image"},{"spell":"web"},{"spell":"whispering wind"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"alarm"},{"spell":"mage armor"},{"spell":"ray of enfeeblement"},{"spell":"shield"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"mage hand"},{"spell":"message"},{"spell":"open/close"},{"spell":"prestidigitation"}]}],"strength":31,"dexterity":10,"constitution":23,"intelligence":16,"wisdom":19,"charisma":16,"baseatk":20,"cmb":32,"cmd":42,"cmd_special":"46 vs. trip","feats":[{"feat":"Alertness"},{"feat":"Combat Expertise"},{"feat":"Greater Vital Strike"},{"feat":"Improved Initiative"},{"feat":"Improved Vital Strike"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":15},{"skill":"Handle Animal","value":23},{"skill":"Intimidate","value":26},{"skill":"Knowledge (arcana)","value":26},{"skill":"Knowledge (history)","value":26},{"skill":"Perception","value":31},{"skill":"Sense Motive","value":6},{"skill":"Spellcraft","value":26},{"skill":"Stealth","value":21},{"skill":"Swim","value":41}],"languages":["Aklo","Boggard","Draconic","Thassilonian"],"sq":["speak with reptiles","swamp stride","water breathing"],"before_combat":"Zarmangarof casts mage armor, mirror image, and shield before combat.","during_combat":"Zarmangarof is under a geas to serve as Sabina's mount and is charmed to be an ally to Queen Ileosa and her minions. These magical effects ensure his cooperation, and he follows Sabina's commands via her Ride skill as demanded, but since he doesn't speak Common and Sabina doesn't speak Draconic, they have limited communication. While he would rather stay in the air and use magic and acid against foes on the ground, he lands as directed by his rider. Once melee begins, each  time Sabina attempts a Ride check to render Zarmangarof flat-footed, the dragon gets to attempt a free Sense Motive check opposed by the result of Sabina's Ride check to realize what she's up to. In any event, once the dragon is reduced to fewer than 100 hit points, his frustration gets the better of him anyway and he turns on Sabina in anger. Once the dragon lashes out at Sabina, he immediately takes a -3 penalty to each of his ability scores from the geas. If, at any time, the charm monster effect on the dragon is dispelled, he takes to the air and uses breath weapons and magic against the PCs and Sabina alike unless he feels confident that he can finish the party off without putting himself in danger.","morale":"Zarmangarof fights to the death.","source":"Curse Of The Crimson Throne Chapter 6, Pathfinder RPG Bestiary 92"},{"name":"Gray Maiden Palace Guard","cr":8,"xp":4800,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":9}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":24,"ac_touch":11,"ac_flat_footed":23,"ac_mods":"+10 armor, +1 Dex, +3 shield","hp":99,"hd":"9d10+45","hd_value":9,"fort":11,"ref":5,"will":5,"save_mods":"Will: +2 vs. fear","speed":[{"type":"land","speed":30}],"melee":"+1 longsword +15 (1d8+7/17-20)","ranged":"+1 composite longbow +12 (1d8+4/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"heavy blades +2, bows +1"}],"strength":14,"dexterity":12,"constitution":18,"intelligence":10,"wisdom":8,"charisma":14,"baseatk":9,"cmb":11,"cmb_special":"+13 bull rush","cmd":22,"cmd_special":"24 vs. bull rush","feats":[{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (longsword)"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Quick Draw"},{"feat":"Shield Wall"},{"feat":"Weapon Focus (longsword)"},{"feat":"Weapon Specialization (longsword)"}],"skills":[{"skill":"Intimidate","value":14},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8}],"languages":["Common"],"sq":["armor training 2"],"gear":"+1 full plate, +1 heavy steel shield, +1 composite longbow (+2 Str) with 20 arrows, +1 longsword, cloak of resistance +1, 31 pp, 4 gp","during_combat":"Gray Maidens prefer to fight in melee, but they are trained to support their sisters with ranged weapons if no opportunity for melee presents itself.","morale":"Gray Maiden palace guards fight to the death.","source":"Curse Of The Crimson Throne Chapter 6"},{"name":"Togomor","cr":15,"xp":51200,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"bloatmage","level":9},{"class":"wizard","level":7}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"senses":["arcane sight","darkvision 60 ft.","see invisibility"],"ac":19,"ac_touch":9,"ac_flat_footed":19,"ac_mods":"+4 armor, -1 Dex, +2 natural, +4 shield","hp":162,"hd":"16d6+103","hd_value":16,"fort":10,"ref":4,"will":10,"defensive_abilities":["contingency","corpulence"],"speed":[{"type":"fly","speed":30,"maneuverability":"average"},{"type":"land","speed":10}],"space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hand of the apprentice","details":"9/day"}],"spellsprepared_caster":"wizard","spellsprepared_caster_level":16,"spellsprepared_concentration":22,"spellsprepared":[{"spell_level":8,"spell_slots":2,"spells":[{"spell":"horrid wilting"},{"spell":"telekinetic sphere"}]},{"spell_level":7,"spell_slots":3,"spells":[{"spell":"prismatic spray"},{"spell":"project image"},{"spell":"quickened displacement"}]},{"spell_level":6,"spell_slots":4,"spells":[{"spell":"disintegrate"},{"spell":"greater dispel magic"},{"spell":"quickened invisibility"},{"spell":"summon monster VI"}]},{"spell_level":5,"spell_slots":5,"spells":[{"spell":"cloudkill"},{"spell":"cone of cold"},{"spell":"feeblemind"},{"spell":"overland flight"},{"spell":"quickened magic missile"}]},{"spell_level":4,"spell_slots":5,"spells":[{"spell":"dimension door","count":2},{"spell":"fear"},{"spell":"greater invisibility"},{"spell":"illusory wall"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"extended false life"},{"spell":"lightning bolt","count":2},{"spell":"nondetection"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"bear's endurance"},{"spell":"blindness/deafness"},{"spell":"glitterdust"},{"spell":"mirror image"},{"spell":"scorching ray"},{"spell":"spider climb"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"feather fall"},{"spell":"grease"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"shield"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"light"},{"spell":"mage hand"},{"spell":"prestidigitation"},{"spell":"touch of fatigue"}]}],"strength":14,"dexterity":8,"constitution":20,"intelligence":22,"wisdom":10,"charisma":12,"baseatk":7,"cmb":9,"cmd":18,"feats":[{"feat":"Bloatmage Initiate (evocation)"},{"feat":"Craft Construct"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Staff"},{"feat":"Craft Wondrous Item"},{"feat":"Extend Spell"},{"feat":"Improved Familiar"},{"feat":"Improved Initiative"},{"feat":"Quicken Spell"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (evocation)"}],"skills":[{"skill":"Acrobatics","value":12},{"skill":"Craft (armor)","value":23},{"skill":"Diplomacy","value":10},{"skill":"Fly","value":0},{"skill":"Knowledge (arcana)","value":25},{"skill":"Knowledge (local)","value":25},{"skill":"Knowledge (nobility)","value":25},{"skill":"Knowledge (planes)","value":25},{"skill":"Perception","value":16},{"skill":"Spellcraft","value":25},{"skill":"Use Magic Device","value":20}],"languages":["Common","Aklo","Draconic","Infernal","Shadowtongue","Shoanti","Varisian; tongues"],"sq":["arcane bond (imp named Pudgyknuckles)","bloat","blood pool","hemophilia","permanent spells","possessed"],"special_abilities":[{"type":"Bloat","kind":"Su","details":"Togomor can exert himself up to three times per day as a free action to gain 1d12 blood points to use with his blood pool ability. This can fill his blood pool to a point beyond his normal limit of 9 blood points, but as long as his blood pool contains more than 9 blood points (but fewer than 18 blood points), Togomor is sickened. If this ability fills his blood pool to 18 blood points or more, he flies into a homicidal range and attacks randomly with his most damaging attacks and abilities at friends and foes alike for 1d6 rounds or until his blood point total is reduced to 0 (whichever comes first); at the end of this rage, Togomor's hit points drop to -1 and he begins dying."},{"type":"Blood Pool","kind":"Su","details":"Togomor has a blood pool that represents an overload to his system of excess blood to extend his arcane abilities beyond their normal level. Togomor's blood pool consists of 9 blood points that can be spent at the time of casting to cast a spell without using that spell's spell slot, leaving it available for further use later in the day. When he does so, Togomor spends blood points equal to the spell slot being retained. Togomor's blood pool refills to its normal maximum of 9 when he rests to regain spells; if he has more than 9 points at this time (due to use of his bloat ability), he gains no additional points from rest. Some bloatmages conduct constant rituals involving leeches or exsanguination in an attempt to regulate their systems and to minimize the results from using the bloat ability (and to help prevent overbloating), but Togomor doesn't use these rituals. Instead, he simply avoids using his bloat ability until his blood pool is at 5 or lower."},{"type":"Contingency","details":"If Togomor snaps his fingers (a swift action as long as he has a hand free), a stoneskin spell activates on him."},{"type":"Corpulence","kind":"Ex","details":"Togomor is so massive that his rolls of fatty, blood-laden flesh grant him a +2 natural armor bonus but reduce his base speed by 10 feet-combined with the fact that his weight results in him carrying a medium load, this means his speed is effectively 10 feet."},{"type":"Hemophilia","kind":"Ex","details":"Togomor is particularly susceptible to bleed effects, and the DC of any Heal check to stop a bleed effect on him is 5 higher than normal. In addition, if Togomor takes bleed damage, he loses 1 blood point from his blood pool; this loss of blood points is cumulative for multiple bleed attacks, but not each time he takes damage from the same attack."},{"type":"Permanent Spells","details":"Togomor has made the following spells permanent on himself: arcane sight, darkvision, see invisibility, and tongues."},{"type":"Possessed","kind":"Su","details":"Togomor is possessed by the belier devil Sermignatto, who languishes on the Ethereal Plane as long as he controls the bloatmage."}],"gear":"handy haversack, headband of vast intelligence +4 (grants ranks in Acrobatics and Use Magic Device), necklace of adaptation, ring of keys (opens all locks in the castle unless the lock's description says otherwise), spell component pouch, 20 gp, 12 cp, scroll of break enchantment, scroll of greater dispel magic, scroll of greater teleport, scrolls of stoneskin (2), scroll of wall of force (CL 10th),  staff of evocation (10 charges)","before_combat":"Togomor casts extended false life, overland flight, mage armor, and nondetection on himself every morning. Once the castle's alarm is raised, Togomor takes the time to cast shield and bear's endurance before he responds to the alarm.","during_combat":"It's unlikely for the PCs to actually encounter Togomor here, unless this room happens to be their first target on visiting the castle. If confronted here before he prepares a defense, Togomor uses dimension door to travel to area A59, casts his preparatory spells, and then either waits for the PCs to confront him there or waits for them to trigger an alarm elsewhere, whereupon he casts greater invisibility and then uses dimension door to that location to offer aid. See area A45 for sample tactics tailored to that location; you can use most of these tactics anywhere else in the castle with a little modification.","morale":"Togomor doesn't have control of his actions as long as he remains possessed, but Sermignatto doesn't take unnecessary risks with his puppet. If reduced to fewer than 30 hit points, Togomor flees via dimension door to area A59, where he makes his last stand.","source":"Curse Of The Crimson Throne Chapter 6, Pathfinder Campaign Setting: City of Strangers 61"},{"name":"False Ileosa","cr":9,"xp":6400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":1},{"class":"bard","level":9}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"templates_applied":"simulacrum","init":3,"ac":28,"ac_touch":23,"ac_flat_footed":25,"ac_mods":"+5 armor, +10 deflection, +3 Dex","hp":87,"hd":"10d8+39","hd_value":10,"fort":6,"ref":9,"will":6,"save_mods":"+2 morale bonus vs. charm and fear, +4 vs. bardic performance, language-dependent, and sonic","defensive_abilities":["redirection"],"immunities":["illusions","mind-affecting effects"],"speed":[{"type":"land","speed":30}],"melee":"+1 returning dagger +12 (1d4+5/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 25 rounds/day","details":"move action; countersong, dirge of doom, distraction, fascinate [DC 19], inspire competence +3, inspire courage +2, inspire greatness, suggestion [DC 19]"}],"spellsknown_caster":"bard","spellsknown_caster_level":9,"spellsknown_concentration":14,"spellsknown":[{"spell_level":3,"spell_slots":4,"spells":[{"spell":"charm monster"},{"spell":"confusion"},{"spell":"displacement"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":5,"spells":[{"spell":"hold person"},{"spell":"mirror image"},{"spell":"misdirection"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":7,"spells":[{"spell":"feather fall"},{"spell":"grease"},{"spell":"hideous laughter"},{"spell":"saving finale"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"message"},{"spell":"open/close"},{"spell":"prestidigitation"}]}],"strength":10,"dexterity":16,"constitution":16,"intelligence":9,"wisdom":7,"charisma":20,"baseatk":6,"cmb":8,"cmd":19,"feats":[{"feat":"Arcane Strike"},{"feat":"Fencing Grace"},{"feat":"Harmonic Spell"},{"feat":"Spell Focus (enchantment)"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Intimidate","value":18},{"skill":"Knowledge (arcana)","value":3},{"skill":"Knowledge (history)","value":9},{"skill":"Knowledge (local)","value":9},{"skill":"Knowledge (nobility)","value":9},{"skill":"Perception","value":10},{"skill":"Perform (oratory)","value":18},{"skill":"Perform (sing)","value":18},{"skill":"Use Magic Device","value":18}],"languages":["Common"],"sq":["bardic knowledge +4","lore master 1/day","versatile performances (oratory, sing)"],"special_abilities":[{"type":"Crimson Throne","kind":"Su","details":"As long as she remains seated in the Crimson Throne, the false Ileosa gains a +10 deflection bonus to her AC and is immune to illusions and mind-affecting effects."},{"type":"Redirection","kind":"Su","details":"As long as this simulacrum lives, any divination spell that attempts to locate or otherwise target the real Queen Ileosa is instead redirected to target this simulacrum. The caster of the divination spell has a small chance to notice the redirection with a successful DC 40 Spellcraft check as the divination spell is cast, but even if the redirection isn'ted, it remains impossible to tell where the effect was redirected from. This effect also affects long-distance spells like demand, dream, nightmare, and sending, but not mental communication such as telepathy."}],"gear":"+1 glamered chain shirt, +1 returning dagger, replica nonmagical Crown of Fangs worth 5,000 gp","during_combat":"The false Ileosa starts combat by using inspire courage on all her allies, then maintains that performance as she casts spells using Harmonic Spell, starting with displacement on the first round. In each subsequent round, she casts suggestion on one PC, suggesting he abandon his weapons and leave Korvosa. She relies on her guardians to prevent anyone from engaging her in melee, but if this tactic fails, she draws her dagger and fights back as best she can.","morale":"The false Ileosa fights until destroyed. Once reduced to 0 hit points, she suddenly becomes rigid and motionless. A moment later, her features run red as she melts swiftly into a pool of blood. A character who succeeds at a DC 27 Spellcraft check recognizes she was some form of variant simulacrum, although further details are not available until the PCs can study the Everdawn Pool in the Sunken Queen.","source":"Curse Of The Crimson Throne Chapter 6"},{"name":"Vavana Dhatri","cr":9,"xp":6400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"enchanter","level":9}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":3,"auras":["despair (30 ft., 9 rounds/day)"],"ac":25,"ac_touch":17,"ac_flat_footed":22,"ac_mods":"+4 armor, +3 defending dagger, +1 deflection, +3 Dex, +4 shield","hp":88,"hd":"9d6+54","hd_value":9,"fort":9,"ref":8,"will":8,"speed":[{"type":"land","speed":30}],"melee":"+3 defending dagger +3 (1d4-1/19-20)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"7/day","spells":[{"spell":"dazing touch"}]}],"spellsprepared_caster":"enchanter","spellsprepared_caster_level":9,"spellsprepared_concentration":13,"spellsprepared":[{"spell_level":5,"spell_slots":2,"spells":[{"spell":"dominate person"},{"spell":"feeblemind"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"charm monster"},{"spell":"crushing despair"},{"spell":"dimension door"},{"spell":"phantasmal killer"}]},{"spell_level":3,"spell_slots":5,"spells":[{"spell":"dispel magic"},{"spell":"displacement"},{"spell":"fireball"},{"spell":"hold person"},{"spell":"suggestion"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"acid arrow"},{"spell":"cat's grace"},{"spell":"hideous laughter"},{"spell":"mirror image"},{"spell":"scorching ray"},{"spell":"touch of idiocy"}]},{"spell_level":1,"spell_slots":6,"spells":[{"spell":"charm person"},{"spell":"grease"},{"spell":"mage armor"},{"spell":"shield"},{"spell":"silent image"},{"spell":"unseen servant"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"arcane mark"},{"spell":"light"},{"spell":"prestidigitation"}]}],"prohibited_schools":"divination, necromancy","strength":8,"dexterity":16,"constitution":18,"intelligence":18,"wisdom":10,"charisma":14,"baseatk":4,"cmb":3,"cmd":20,"feats":[{"feat":"Combat Casting"},{"feat":"Craft Wand"},{"feat":"Greater Spell Focus (enchantment)"},{"feat":"Greater Spell Specialization"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (enchantment)"},{"feat":"Spell Specialization (suggestion)"},{"feat":"Toughness"}],"skills":[{"skill":"Bluff","value":14},{"skill":"Diplomacy","value":14},{"skill":"Intimidate","value":14},{"skill":"Knowledge (arcana)","value":16},{"skill":"Perception","value":9},{"skill":"Sense Motive","value":9},{"skill":"Spellcraft","value":16}],"languages":["Common","Elven","Infernal","Shoanti","Varisian","Vudrani"],"sq":["arcane bond (wand of pain strike)","enchanting smile","wealth"],"special_abilities":[{"type":"Wealth","details":"Vavana's position among the Gray Maidens has allowed her increased wealth and potent gear, and her CR is 1 point higher than normal as a result."}],"gear":"+3 defending dagger, cloak of resistance +2, ring of protection +1, spell component pouch, 49 pp, 3 gp, scroll of mind fog (2), wand of bear's endurance (10 charges), wand of disfiguring touch (15 charges), wand of magic missile (CL 9th, 20 charges), wand of pain strike (32 charges)","before_combat":"Vavana casts mage armor, shield, cat's grace, false life, and unseen servant and uses a charge from her wand of bear's endurance before combat.","during_combat":"Vavana uses her +3 defending dagger to bolster her Armor Class but remains within 5 ft. of the false Ileosa at all times. She casts displacement on the first round of combat, followed by mirror image. She uses a scroll of mind fog on the third round. On the fourth round, she uses her offensive spells against the PCs, using dominate person on non-spellcasters (ordering them to leave the combat and await further instructions to serve, later, as her personal assistants) or feeblemind on spellcasters. She's fond of using suggestion and charms to compel victims to discard their gear or remove armor-discarded items are carried away by her unseen servant. She saves the use of her wands for tormenting prisoners or training new Gray Maidens, and is loath to use them in combat.","morale":"Vavana retreats to area A56 via dimension door if the false Ileosa is slain, or if she herself is reduced to fewer than 20 hit points. From there, she gathers her spellbooks before attempting to flee the castle and seek shelter with the Arkonas.","source":"Curse Of The Crimson Throne Chapter 6"},{"name":"Venster Arabasti","cr":6,"xp":2400,"race":"Tiefling","gender":"Male","age_category":"Adult","classes":[{"class":"aristocrat","level":6}],"alignment":"N","size":"Medium","type":"undead","sub_types":["incorporeal"],"templates_applied":"ghost","init":3,"senses":["darkvision 60 ft."],"ac":17,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+4 deflection, +3 Dex","hp":57,"hd":"6d8+30","hd_value":6,"fort":6,"ref":5,"will":6,"defensive_abilities":["channel resistance +4","incorporeal","rejuvenation"],"immunities":["undead traits"],"resists":["cold 5","electricity 5","fire 5"],"speed":[{"type":"fly","speed":30,"maneuverability":"perfect"}],"melee":"corrupting touch +7 touch (6d6)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"darkness  Special Attacks telekinesis"}]}],"dexterity":16,"intelligence":14,"wisdom":13,"charisma":18,"baseatk":4,"cmb":7,"cmd":21,"feats":[{"feat":"Deceitful"},{"feat":"Skill Focus (Disguise)"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Bluff","value":17},{"skill":"Diplomacy","value":13},{"skill":"Disguise","value":18},{"skill":"Fly","value":11},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":25}],"languages":["Common","Infernal","Shoanti","Varisian"],"special_abilities":[{"type":"Rejuvenation","kind":"Ex","details":"Venster's rejuvenation works more swiftly than that of most ghosts. When destroyed, he rejuvenates after 2d6 rounds. His method of permanent destruction is detailed below, under Development."}],"during_combat":"If attacked, Venster is able to focus his undead nature enough to fight back, using his telekinesis ability to force intruders out of his abode or lashing out with his corrupting touch.","morale":"Venster fights until destroyed, only to rejuvenate swiftly after such destruction. When he rejuvenates, he doesn't attack again until he is himself attacked.","source":"Curse Of The Crimson Throne Chapter 6, Pathfinder RPG Bestiary 264, 144"},{"name":"Boggard Champion","cr":10,"xp":9600,"race":"Boggard","age_category":"Adult","classes":[{"class":"barbarian","level":8}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["boggard"],"init":4,"senses":["darkvision 60 ft.","low-light vision"],"ac":17,"ac_touch":8,"ac_flat_footed":17,"ac_mods":"+6 armor, +3 natural, -2 rage","hp":150,"hd":"3d8+8d12+85","hd_value":11,"fort":15,"ref":3,"will":8,"save_mods":"+2 resistance bonus vs. confusion, insanity, polymorph, and lawful effects","defensive_abilities":["fortification 25%","improved uncanny dodge","trap sense +2"],"dr":"1/-","speed":[{"type":"land","speed":20},{"type":"swim","speed":30}],"melee":"+1 thundering greatclub +19 (1d10+11/19-20), sticky tongue +12 touch (special)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"rage","details":"22 rounds/day"},{"type":"rage powers","details":"chaos totem, clear mind, knockdown, lesser chaos totem"}],"strength":24,"dexterity":11,"constitution":23,"intelligence":6,"wisdom":12,"charisma":10,"baseatk":10,"cmb":17,"cmd":25,"feats":[{"feat":"Improved Critical (greatclub)"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Weapon Focus (greatclub)"}],"skills":[{"skill":"Escape Artist","value":2},{"skill":"Perception","value":17},{"skill":"Stealth","value":8,"special":"+8 in swamps"},{"skill":"Swim","value":13}],"languages":["Boggard"],"sq":["fast movement","hold breath","swamp stride","terrifying croak"],"gear":"+2 hide armor, +1 thundering greatclub","during_combat":"The boggards rage on the first round and use their terrifying croak as soon as they encounter the PCs; the volume is enough to alert all nearby areas to the event  They use their tongues to keep archers, rogues, flying enemies, and spellcasters from gaining ranged advantages, and generally focus on one target per two boggards.","morale":"The boggard champions fight to the death.","source":"Curse Of The Crimson Throne Chapter 6, Pathfinder RPG Bestiary 37"},{"name":"Beirawash","cr":15,"xp":51200,"race":"devilfish","age_category":"Adult","alignment":"NE","size":"Gargantuan","type":"magical beast","sub_types":["aquatic"],"templates_applied":"advanced","init":5,"senses":["darkvision 60 ft.","low-light vision","see in darkness"],"ac":30,"ac_touch":12,"ac_flat_footed":24,"ac_mods":"+5 Dex, +1 dodge, +18 natural, -4 size","hp":273,"hd":"15d10+135","hd_value":15,"fort":18,"ref":14,"will":8,"resists":["cold 10"],"speed":[{"type":"land","speed":10},{"type":"swim","speed":40}],"melee":"tentacles +25 (8d6+21/19-20 plus grab)","space":"20 ft.","reach":"15 ft.","special_attacks":[{"type":"poison","details":"DC 26"},{"type":"savage bite","details":"6d6+21/18-20 plus poison"},{"type":"unholy blood","details":"DC 26"}],"strength":38,"dexterity":20,"constitution":28,"intelligence":7,"wisdom":16,"charisma":12,"baseatk":15,"cmb":33,"cmb_special":"+37 grapple","cmd":49,"cmd_special":"cant be tripped","feats":[{"feat":"Dodge"},{"feat":"Improved Critical (tentacle)"},{"feat":"Improved Natural Armor (4)"},{"feat":"Improved Natural Attack (tentacle)"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":20},{"skill":"Swim","value":26}],"languages":["Common","Abyssal","Aquan"],"sq":["compression","water dependency"],"during_combat":"Beirawash attacks intruders on sight, jetting up to engage them if necessary. He pursues foes throughout the Sunken Queen. Unlike most devilfish, Beirawash's body is particularly malleable and he can move through areas as narrow as 5 ft. wide without squeezing, but he doesn't pursue foes out of the water or beyond 100 ft. from the Sunken Queen itself.","morale":"Even after being subjected to countless charm monster spells, the immense devilfish secretly rankles at the change in his status; if the PCs can dispel Ileosa's current charm monster effect, the devilfish breaks off combat and attempts to escape. Barring that, he might try to bargain with the PCs, offering up his treasure in area B3 as a bribe to let him escape. Without being freed from the enchantment, he fights to the death.","source":"Curse Of The Crimson Throne Chapter 6, Pathfinder RPG Bestiary 2 292, 88"},{"name":"Ithier","cr":17,"xp":102400,"race":"scarlet walker","age_category":"Adult","alignment":"LE","size":"Huge","type":"outsider","sub_types":["evil","extraplanar","lawful"],"templates_applied":"advanced, sorcerer","init":11,"senses":["bloodsense","darkvision 60 ft."],"ac":32,"ac_touch":20,"ac_flat_footed":20,"ac_mods":"+11 Dex, +1 dodge, +12 natural, -2 size","hp":272,"hd":"19d10+152","hd_value":19,"hp_mods":"fast healing 10","fort":13,"ref":22,"will":18,"defensive_abilities":["evasion","unusual anatomy (50%)"],"immunities":["acid","cold","poison"],"sr":27,"weaknesses":["vulnerable to electricity"],"speed":[{"type":"climb","speed":40},{"type":"land","speed":40}],"speed_mod":"air walk","melee":"2 claws +28 (3d6+9/19-20 plus bleed), tentacle +23 (4d6+4 plus paralysis and bleed)","space":"15 ft.","reach":"30 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"blood-draining gaze"},{"type":"long limbs","details":"+15 ft."},{"type":"paralysis","details":"1d4 rounds, DC 26"}],"spell_like_abilities_caster_level":16,"spell_like_abilities_concentration":25,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"air walk"},{"spell":"detect thoughts"}]},{"frequency":"at-will","spells":[{"spell":"sending"}]},{"frequency":"1/day","spells":[{"spell":"feeblemind"},{"spell":"insanity"}]},{"frequency":"3/day","spells":[{"spell":"confusion"},{"spell":"demand"},{"spell":"quickened lesser confusion"}]},{"frequency":"12/day","spells":[{"spell":"acidic ray","details":"1d6+8 acid"}]}],"spellsknown_caster":"sorcerer creature","spellsknown_caster_level":19,"spellsknown_concentration":28,"spellsknown":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"greater dispel magic"}]},{"spell_level":5,"spell_slots":4,"spells":[{"spell":"dominate person"},{"spell":"mind fog"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"enervation"},{"spell":"greater invisibility"}]}],"strength":28,"dexterity":33,"constitution":25,"intelligence":18,"wisdom":24,"charisma":29,"baseatk":19,"cmb":30,"cmd":52,"cmd_special":"60 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Natural Attack (claw)"},{"feat":"Mobility"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (lesser confusion)"},{"feat":"Spring Attack"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":33},{"skill":"Climb","value":17},{"skill":"Intimidate","value":31},{"skill":"Knowledge (arcana)","value":26},{"skill":"Knowledge (nature)","value":26},{"skill":"Knowledge (planes)","value":26},{"skill":"Perception","value":29},{"skill":"Sense Motive","value":29},{"skill":"Spellcraft","value":23},{"skill":"Stealth","value":25},{"skill":"Use Magic Device","value":28}],"languages":["Abyssal","Aklo","Infernal","Thassilonian; telepathy 300 ft."],"sq":["bloodline arcana (+50% duration on polymorph effects)","compression","no breath"],"special_abilities":[{"type":"Blood-Draining Gaze","kind":"Su","details":"All creatures within 20 ft. of a scarlet walker are subject to the monster's eerie blood-draining gaze. Affected creatures must succeed at a DC 26 Fortitude save or thin streams of blood pour from their eyes, flowing through the air and into the eye-socket-like pits in Ithier's face. This doesn't impact the victim's vision, but deals 1 point of Constitution damage and sickens the victim for 1 round from the hideous pain. A creature already suffering from a bleed effect takes a -4 penalty on the saving throw. This is a bleed effect. The save DC is Constitution-based."},{"type":"Bloodsense","kind":"Su","details":"Ithier can sense living creatures with blood in their veins and undead creatures that feed on blood (such as vampires). This ability functions like blindsight to a range of 60 feet."}],"during_combat":"Ithier casts mind fog on the first round of combat and uses quickened lesser confusion each round on a fighter, a barbarian, or another well-armed PC.  The scarlet walker casts greater invisibility on the second round, following that up with its mind-affecting spells and spell-like abilities. It keeps Ileosa informed of the battle via telepathy. It pursues foes throughout the Sunken Queen, but not into the flooded areas. If it manages to affect the target of the soultrapping gem in area 9 with dominate person or demand, it orders that person to go fetch the gemstone and thus fall victim to the gem's effects.","morale":"Ithier fights to the death.","source":"Curse Of The Crimson Throne Chapter 6, Pathfinder RPG Monster Codex 248, Pathfinder Adventure Path: Rise of the Runelords Anniversary Edition 414"},{"name":"Ileosa's Fury","cr":12,"xp":19200,"race":"Erinyes devil","age_category":"Adult","classes":[{"class":"fighter","level":4}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["devil","evil","extraplanar","lawful"],"init":9,"senses":["darkvision 60 ft.","see in darkness","true seeing"],"ac":27,"ac_touch":14,"ac_flat_footed":23,"ac_mods":"+7 armor, +3 Dex, +1 dodge, +6 natural","hp":166,"hd":"13d10+95","hd_value":13,"fort":18,"ref":17,"will":11,"save_mods":"Will: +1 vs. fear","dr":"5/good","immunities":["bleed","fire","poison"],"resists":["acid 10","cold 10"],"sr":19,"speed":[{"type":"fly","speed":50,"maneuverability":"good"},{"type":"land","speed":30}],"melee":"+1 flaming returning trident +22 (1d8+10/19-20 plus 1d6 fire)","ranged":"+1 flaming returning trident +24 (1d8+10/19-20 plus 1d6 fire) or rope +22 touch (entangle)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":19,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"true seeing"}]},{"frequency":"at-will","spells":[{"spell":"fear","details":"single target"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"minor image"},{"spell":"unholy blight"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"2 bearded devils 50%, level 3"}]}],"strength":24,"dexterity":28,"constitution":24,"intelligence":12,"wisdom":18,"charisma":24,"baseatk":13,"cmb":20,"cmd":40,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Critical (trident)"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Point-Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Rapid Shot"},{"feat":"Shot on the Run"},{"feat":"Weapon Focus (trident)"},{"feat":"Weapon Specialization (trident)"}],"skills":[{"skill":"Acrobatics","value":21},{"skill":"Bluff","value":19},{"skill":"Diplomacy","value":16},{"skill":"Escape Artist","value":12},{"skill":"Fly","value":19},{"skill":"Intimidate","value":19},{"skill":"Knowledge (planes)","value":7},{"skill":"Knowledge (religion)","value":7},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":15}],"languages":["Common","Celestial","Draconic","Infernal","telepathy 100 ft."],"sq":["armor training 1","entangle","Everdawn infusion"],"special_abilities":[{"type":"Everdawn Infusion","kind":"Ex","details":"The furies have bathed in the Everdawn Pool recently. As a result, they can teleport in the Sunken Queen without restriction, modify their hit point totals with their Charisma modifiers rather than their Constitution modifiers, and are immune to bleed effects."}],"gear":"+1 chainmail, +1 flaming returning trident, cloak of resistance +1, silk rope (50 ft.)","during_combat":"The furies prefer to fight in melee, wielding their tridents two-handed and using Power Attack, but each round one of them hits the largest group of enemies she can with an unholy blight; if their foes prove resistant to this tactic, the erinyes instead joins her companions in melee. If a single foe proves particularly troublesome, the four devils target that foe with fear spells, hoping at least one of the spells will take effect-but keep in mind the furies are forewarned of the PCs's abilities and won't  bother trying to cast fear on a paladin or other character they know is immune to this effect. They generally use their rope attacks against clerics or other healers. They avoid using their summon devil spell-like ability, saving that for emergencies or for a fight at Ileosa's side.","morale":"Bound by contract, the furies fight to the death.","source":"Curse Of The Crimson Throne Chapter 6, Pathfinder RPG Bestiary 75"},{"name":"Bahor","cr":14,"xp":38400,"race":"rakshasa","gender":"Male","age_category":"Adult","classes":[{"class":"rogue","level":8}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["native","shapechanger"],"init":12,"senses":["darkvision 60 ft."],"ac":36,"ac_touch":19,"ac_flat_footed":27,"ac_mods":"+4 armor, +8 Dex, +1 dodge, +9 natural, +4 shield","hp":207,"hd":"8d8+10d10+116","hd_value":18,"fort":11,"ref":21,"will":12,"defensive_abilities":["evasion","improved uncanny dodge","trap sense +2"],"dr":"15/good and piercing","sr":25,"speed":[{"type":"land","speed":40}],"melee":"+2 kukri +27 (1d4+7/15-20), bite +22 (1d6+2), claw +22 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"detect thoughts"},{"type":"sneak attack +4d6 plus 4 bleed"}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":7,"spellsknown_concentration":12,"spellsknown":[{"spell_level":3,"spell_slots":5,"spells":[{"spell":"fly"},{"spell":"lightning bolt"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"invisibility"},{"spell":"scorching ray"},{"spell":"web"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"charm person"},{"spell":"mage armor"},{"spell":"obscuring mist"},{"spell":"protection from good"},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"arcane mark"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"}]}],"strength":20,"dexterity":26,"constitution":22,"intelligence":15,"wisdom":12,"charisma":20,"baseatk":16,"cmb":21,"cmd":40,"feats":[{"feat":"Arcane Strike"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Critical (kukri)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Multiattack"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (kukri)"}],"skills":[{"skill":"Acrobatics","value":29},{"skill":"Bluff","value":30},{"skill":"Diplomacy","value":26},{"skill":"Disguise","value":34},{"skill":"Fly","value":18},{"skill":"Intimidate","value":26},{"skill":"Knowledge (local)","value":17},{"skill":"Knowledge (nobility)","value":14},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":22}],"languages":["Common","Infernal","Undercommon","Vudrani"],"sq":["change shape (any humanoid; alter self)","rogue talents (bleeding attack +4, combat trick, finesse rogue, weapon training)","trapfinding +4"],"gear":"+2 kukri, third eye, keys to all Arkona Palace locks, 19 pp, 2 gp, scroll of sending (3), wand of haste (19 charges), wand of illusory script (12 charges), wand of shield (23 charges)","before_combat":"Bahor casts mage armor as soon as the prospect of combat looms (such as upon hearing a palace alarm activated). He uses his third eye to check the various rooms in his palace for intruders. As soon as his foes seem to be drawing near, he casts shield and protection from good.","during_combat":"Bahor favors spellcasting in combat, and reverts to his true form only if his enemies know that he isn't Human. If his spells are exhausted or proving useless, he uses a charge from his wand of haste, then resorts to melee tactics. He prefers to fight with allies so he can perform sneak attacks. In such a situation, Bahor tries to remain mobile, moving in and out of combat by using Spring Attack to make a single bleeding sneak attack against a foe each round. On his own, he tries to make full attacks so he can add a bite and a claw to his kukri strikes, using Arcane Strike to gain a +1 bonus on all damage rolls.","morale":"Bahor has little interest in risking everything on bad luck. If reduced to fewer than 100 hit points, he  attempts to flee with the aid of invisibility. If he escapes, he retreats to the Cerulean Society guildhall below Old Korvosa to wait things out, and may end up seeking revenge on the PCs at a later date-especially if the PCs interact with the Cerulean Society. Bahor stays behind to fight to the death only if his enemies show that they know of his true nature; allowing anyone to escape his clutches with this knowledge is the thing he fears the most.","source":"Curse Of The Crimson Throne Chapter Appendix, Pathfinder RPG Bestiary 231"},{"name":"\"glorio Arkona\"","cr":14,"xp":38400,"race":"Rakshasa","age_category":"Adult","classes":[{"class":"rogue","level":8}],"alignment":"LE","size":"Medium","type":"outsider","sub_types":["native","shapechanger"],"init":12,"ac":36,"ac_touch":19,"ac_flat_footed":27,"ac_mods":"+4 armor, +8 Dex, +1 dodge, +9 natural, +4 shield","hp":207,"hd":"8d8+10d10+116","hd_value":18,"fort":11,"ref":21,"will":12,"defensive_abilities":["evasion","improved uncanny dodge","trap sense +2"],"speed":[{"type":"land","speed":30}],"melee":"+2 kukri +27 (1d4+7/15-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"detect thoughts"},{"type":"sneak attack +4d6 plus 4 bleed"}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":7,"spellsknown_concentration":12,"spellsknown":[{"spell_level":3,"spell_slots":5,"spells":[{"spell":"fly"},{"spell":"lightning bolt"}]},{"spell_level":2,"spell_slots":7,"spells":[{"spell":"invisibility"},{"spell":"scorching ray"},{"spell":"web"}]},{"spell_level":1,"spell_slots":8,"spells":[{"spell":"charm person"},{"spell":"mage armor"},{"spell":"obscuring mist"},{"spell":"protection from good"},{"spell":"ray of enfeeblement"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"arcane mark"},{"spell":"detect magic"},{"spell":"mage hand"},{"spell":"mending"},{"spell":"message"},{"spell":"prestidigitation"}]}],"strength":20,"dexterity":26,"constitution":22,"intelligence":15,"wisdom":12,"charisma":20,"baseatk":16,"cmb":21,"cmd":40,"feats":[{"feat":"Arcane Strike"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Critical (kukri)"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"},{"feat":"Mobility"},{"feat":"Multiattack"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (kukri)"}],"skills":[{"skill":"Acrobatics","value":29},{"skill":"Bluff","value":30},{"skill":"Diplomacy","value":26},{"skill":"Disguise","value":34},{"skill":"Fly","value":18},{"skill":"Intimidate","value":26},{"skill":"Knowledge (local)","value":17},{"skill":"Knowledge (nobility)","value":14},{"skill":"Perception","value":26},{"skill":"Sense Motive","value":22}],"languages":["Common","Infernal","Undercommon","Vudrani"],"sq":["change shape (any humanoid; alter self)","rogue talents (bleeding attack +4, combat trick, finesse rogue, weapon training)","trapfinding +4"],"gear":"+2 kukri, third eye, 192 gp, scroll of sending (3), wand of haste (19 charges), wand of illusory script (12 charges), wand of shield (23 charges)","before_combat":"Same as Bahor's tactics.","during_combat":"When appearing as Glorio (or in any Human guise, for that matter), Bahor prefers to avoid combat if at all possible, since his Human form lacks some of his true form's key defenses (particularly damage reduction and spell resistance). If he must fight, he does so with his kukri, relying on allies to flank foes as possible. Against foes he feels confident he can defeat quickly, or who already know his secret, he reverts to his true form as soon as possible.","morale":"If faced with a combat not to his advantage, yet in a situation where he doesn't wish to reveal his true shape, Glorio flees at once, using invisibility if able. He hopes to return to Arkona Palace. If confronted there, he has additional allies upon whom he can rely.","source":"Curse Of The Crimson Throne Chapter Appendix, Pathfinder RPG Bestiary 231"},{"name":"Cressida Kroft","cr":9,"xp":6400,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":1},{"class":"fighter","level":9}],"alignment":"LN","size":"Medium","type":"humanoid","sub_types":["human"],"init":0,"ac":23,"ac_touch":10,"ac_flat_footed":23,"ac_mods":"+8 armor, +5 shield","hp":97,"hd":"1d8+9d10+39","hd_value":10,"fort":8,"ref":3,"will":10,"save_mods":"Will: +2 vs. fear","speed":[{"type":"land","speed":20,"special":"30 ft. without armor"}],"melee":"+1 longsword +16 (1d8+7/17-20)","ranged":"mwk composite longbow +11 (1d8+3/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"weapon training","details":"heavy blades +2, bows +1"}],"strength":15,"dexterity":10,"constitution":15,"intelligence":10,"wisdom":12,"charisma":16,"baseatk":9,"cmb":11,"cmd":21,"feats":[{"feat":"Greater Shield Focus"},{"feat":"Greater Weapon Focus (longsword)"},{"feat":"Improved Critical (longsword)"},{"feat":"Iron Will"},{"feat":"Persuasive"},{"feat":"Power Attack"},{"feat":"Shield Focus"},{"feat":"Steadfast Personality"},{"feat":"Toughness"},{"feat":"Weapon Focus (longsword)"},{"feat":"Weapon Specialization (longsword)"}],"skills":[{"skill":"Diplomacy","value":16},{"skill":"Intimidate","value":16},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":10}],"languages":["Common"],"sq":["armor training 2"],"gear":"+2 chainmail, +1 heavy steel shield, +1 longsword, mwk composite longbow (+2 Str) with 20 arrows, belt of mighty constitution +2, 64 gp, potion of cure moderate wounds","during_combat":"Cressida prefers to fight in melee if possible, saving her arrows for foes who avoid hand-to-hand combat. In a fight, Cressida uses Power Attack (taking a -3 penalty on attack rolls but gaining a +6 bonus on damage rolls); if she misses a foe entirely for 2 rounds of combat, though, she switches back to regular attacks.","morale":"Cressida prefers to save her potion of cure moderate wounds to aid allies, but if she's reduced to fewer than 20 hit points and escape isn't an option, she drinks the potion and fights defensively until the odds change in her favor or she sees an opportunity to escape. She won't abandon friends or her subordinates to certain death; if presented with overwhelming odds, she works with allies to make a fighting retreat to safety, but brings up the rear herself, and is willing to give up her life to buy her allies a chance to flee.","source":"Curse Of The Crimson Throne Chapter Appendix"},{"name":"Ileosa Arabasti","cr":21,"xp":409600,"race":"human","gender":"Female","age_category":"Adult","classes":[{"class":"aristocrat","level":2},{"class":"bard","level":18}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"templates_applied":"erinyes-devil-bound","init":10,"senses":["arcane sight","darkvision 60 ft.","see in darkness","true seeing"],"ac":43,"ac_touch":26,"ac_flat_footed":34,"ac_mods":"+8 armor, +5 deflection, +9 Dex, +2 insight, +9 natural","hp":391,"hd":"20d8+298","hd_value":20,"hp_mods":"regeneration 20 (Serithtial)","fort":21,"ref":28,"will":22,"save_mods":"+4 morale bonus vs. charm and fear, +4 vs. poison, +4 vs. bardic performance, language-dependent, and sonic","defensive_abilities":["freedom of movement"],"dr":"10/ adamantine (70 hp)","immunities":["bleed"],"resists":["fire 30"],"sr":22,"weaknesses":["contract bound","susceptible to Serithtial"],"speed":[{"type":"fly","speed":60,"maneuverability":"average"},{"type":"land","speed":30}],"melee":"+4 glamered Human-bane icy burst speed rapier +32 (1d6+21/15-20 plus 1d6 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 51 rounds/day","details":"swift; countersong, dirge of doom, distraction, fascinate [DC 32], frightening tune [DC 32], inspire competence +5, inspire courage +4, inspire greatness, inspire heroics, mass suggestion [DC 32], soothing performance, suggestion [DC 32]"}],"spell_like_abilities_caster_level":20,"spell_like_abilities_concentration":33,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"summon","details":"or 1 ice devil 100%, 1 barbed devil, 1 bone devil, 1 erinyes, 1 bearded devil, 1 lemure, level 9"}]},{"frequency":"3/day","spells":[{"spell":"fear","details":"single target"},{"spell":"unholy blight"}]}],"spellsknown_caster":"bard","spellsknown_caster_level":18,"spellsknown_concentration":31,"spellsknown":[{"spell_level":6,"spell_slots":5,"spells":[{"spell":"geas/quest"},{"spell":"getaway"},{"spell":"irresistible dance"},{"spell":"project image"}]},{"spell_level":5,"spell_slots":7,"spells":[{"spell":"greater dispel magic"},{"spell":"mind fog"},{"spell":"shadow walk"},{"spell":"song of discord"}]},{"spell_level":4,"spell_slots":8,"spells":[{"spell":"cure critical wounds"},{"spell":"dimension door"},{"spell":"dominate person"},{"spell":"freedom of movement"},{"spell":"hold monster"}]},{"spell_level":3,"spell_slots":8,"spells":[{"spell":"charm monster"},{"spell":"confusion"},{"spell":"displacement"},{"spell":"gaseous form"},{"spell":"haste"},{"spell":"slow"}]},{"spell_level":2,"spell_slots":8,"spells":[{"spell":"cure moderate wounds"},{"spell":"detect thoughts"},{"spell":"hold person"},{"spell":"mirror image"},{"spell":"misdirection"},{"spell":"suggestion"}]},{"spell_level":1,"spell_slots":9,"spells":[{"spell":"cure light wounds"},{"spell":"feather fall"},{"spell":"grease"},{"spell":"hideous laughter"},{"spell":"saving finale"},{"spell":"silent image"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"message"},{"spell":"open/close"},{"spell":"prestidigitation"}]}],"strength":19,"dexterity":28,"constitution":28,"intelligence":16,"wisdom":14,"charisma":36,"baseatk":14,"cmb":22,"cmd":44,"feats":[{"feat":"Arcane Strike"},{"feat":"Craft Wondrous Item"},{"feat":"Fencing Grace"},{"feat":"Forge Ring"},{"feat":"Greater Spell Focus (enchantment)"},{"feat":"Harmonic Spell"},{"feat":"Improved Critical (rapier)"},{"feat":"Spell Focus (enchantment)"},{"feat":"Toughness"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (rapier)"}],"skills":[{"skill":"Acrobatics","value":37},{"skill":"Appraise","value":4},{"skill":"Bluff","value":37},{"skill":"Climb","value":5},{"skill":"Diplomacy","value":37},{"skill":"Disable Device","value":8},{"skill":"Disguise","value":14},{"skill":"Escape Artist","value":10},{"skill":"Fly","value":37},{"skill":"Handle Animal","value":27},{"skill":"Heal","value":3},{"skill":"Intimidate","value":33},{"skill":"Knowledge (arcana)","value":36},{"skill":"Knowledge (history, local, nobility)","value":26},{"skill":"Linguistics","value":12},{"skill":"Perception","value":26},{"skill":"Perform (dance)","value":37},{"skill":"Perform (oratory, sing, string instruments, wind instruments)","value":27},{"skill":"Ride","value":10},{"skill":"Sense Motive","value":27},{"skill":"Sleight of Hand","value":10},{"skill":"Spellcraft","value":27},{"skill":"Stealth","value":10},{"skill":"Survival","value":3},{"skill":"Swim","value":5},{"skill":"Use Magic Device","value":32}],"languages":["Common","Aklo","Elven","Giant","Infernal","Shadowtongue","Thassilonian","Varisian; tongues"],"sq":["bardic knowledge +9","contingency","contract-bound","Everdawn infusion","exceptional stats","inherent bonuses","jack-of-all-trades","lore master 3/day","permanent spells","versatile performances (dance, oratory, sing, string, wind)"],"special_abilities":[{"type":"Contingency","details":"Ileosa used a scroll of contingency to set up this effect: if she is ever brought to fewer than 30 hit points, heal (CL 20th) is cast on her."},{"type":"Contract Bound","kind":"Ex","details":"Queen Ileosa forged a contract with an erinyes devil, gaining the benefits of the devil-bound template. If Ileosa dies, she cannot be brought back to life without Sermignatto's permission; if that devil is slain, the contract itself reverts to Sermignatto's hidden master, the Duke of Hell known as Lorthact."},{"type":"Everdawn Infusion","kind":"Ex","details":"Ileosa can cast teleport in the Sunken Queen without restriction. She calculates her hit points using her Charisma modifier rather than her Constitution modifier, and is immune to bleed effects."},{"type":"Exceptional Stats","kind":"Ex","details":"Queen Ileosa was destined from birth to achieve greatness. Her ability scores were generated using 25 points, rather than the standard array. Additionally, she has a potent artifact and her gear was determined as if she were a PC rather than an NPC to account for her vast wealth. These advantages increase her total CR by 1."},{"type":"Inherent Bonuses","details":"With the aid of genie-granted wishes and other expenditures of her wealth, Ileosa has the following inherent bonuses to her ability scores: Strength +3, Dexterity +4, Constitution +4, Intelligence +3, Wisdom +3, Charisma +5."},{"type":"Permanent Spells","details":"Ileosa has arcane sight and tongues as permanent spells, both functioning at CL 16th."},{"type":"Susceptible to Serithtial","kind":"Ex","details":"The infusion of Kazavon into Ileosa's soul allows Serithtial to suppress her regeneration. Each time she takes damage from Serithtial, she must succeed at a DC 25 Fortitude save or gain a negative level as the sacred blade carves away at the power granted to her by the dragon's fangs."},{"type":"True Seeing","kind":"Su","details":"Queen Ileosa continuously benefits from true seeing, as a benefit from her infernal contract."}],"gear":"+4 glamered Human-bane icy burst speed rapier, amulet of natural armor +5, belt of physical might +6 (Str, Dex), boots of teleportation, bracers of armor +8, crimson gown (as wings of flying but takes up the body slot, not the shoulder slot), Crown of Fangs, crystal ball with true seeing, eyes of charming, gloves of arcane striking, handy haversack, headband of mental prowess +4 (Int, Wis; grants ranks in Knowledge [arcana] and Spellcraft), iridescent spindle ioun stone, pale green prism ioun stone, portable hole, ring of splendid security, vibrant purple prism ioun stone (cure serious wounds), gold-and-ruby earrings worth 5,000 gp for the pair, gold anklet set with rubies worth 4,000 gp, gold armband set with rubies worth 3,500 gp, greater quicken metamagic rod, major ring of spell storing (contains heal, stoneskin), wand of magic missile (CL 9th, 34 charges)","before_combat":"Ileosa casts stoneskin (from her ring of spell storing) and freedom of movement before combat, and activates the flight power of her crimson gown. She prepares herself, her four erinyes furies, and five of her six false Ileosas with a getaway spell, using area 9 of the Sunken Queen as the designated location.","during_combat":"When combat starts, Ileosa activates her inspire courage bardic performance and casts project image to create a duplicate of herself amid the PCs while she flies out of melee range. She uses her eyes of charming each round against foes she knows have poor Will saves (her knowledge of the PCs allows her to choose her targets appropriately). The Crown of Fangs casts mirror image on her on the first round, recasting it as necessary as the combat goes on or casting dominate person otherwise. On the second round, she uses her greater quicken metamagic rod to cast quickened mind fog and then summons an ice devil to join the fight. On the third round, she uses her projected image to target a PC with irresistible dance while she casts quickened displacement. She saves her last quickened spell from the rod to cast greater dispel magic to cancel any particularly vexing spell effect. If she manages to control a foe's mind, she's fond of issuing orders like \"Lay down your arms and bow before me!\" or (to the appropriate PC) \"Return to the floor below to find and take the largest gem you discover.\" Once confronted in melee, she fights back with her rapier and uses Arcane Strike when attacking (the bonus damage is included above).","morale":"Ileosa triggers her getaway spell if reduced to 60 or fewer hit points (bringing along any furies or false Ileosas within 30 ft. of her) to retreat to area 9 of the Sunken Queen, then uses the heal spell from her ring and other spells to recover quickly before returning to the fight. Once she rejoins the battle, she fights to the death, unwilling to abandon her plans this close to fruition.","source":"Curse Of The Crimson Throne Chapter Appendix, Pathfinder RPG Bestiary 4 56"}];
